  insert into public.brands (name, website, description, country, status) values ('M.A.D MOSS', 'https://madmoss.com', 'Sea moss gel and mineral wellness brand running its own affiliate program on its own site: affiliates start at 10% commission on every order with room to grow the rate, get a custom link and discount code, a live earnings dashboard and one-tap payouts. The program page states repeatedly that there are no caps and no limits on earnings. Free to join; applications are reviewed personally, usually within a day.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'wellness'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'general', 'madmossbusiness@madmoss.com', null, null, 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct (M.A.D MOSS Affiliate Program)', 10, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://madmoss.com/affiliate/apply.', 'https://madmoss.com/affiliate/apply', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'M.A.D MOSS Affiliate Program', 'https://madmoss.com/affiliate/apply', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://madmoss.com/affiliate/apply', 'brand_site', 'affiliate_program', 'M.A.D MOSS''s own affiliate page recruits sharers and creators: apply in 60 seconds, get a custom code, deep product links and ready-to-post captions, a live earnings dashboard, weekly affiliate calls and one-tap payout requests. Free to join; approval usually within a day.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://madmoss.com/affiliate/apply', 'brand_site', 'commission_rate', 'The brand''s own page publishes the starting rate: ''Start at 10% commission on every order — with the opportunity to grow your rate as you sell'', a 10% follower discount and a 30-day referral tracking window; monthly goal rewards can add +2% commission.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://madmoss.com/affiliate/apply', 'brand_site', 'commission_cap', 'The brand''s own page states the cap explicitly three times: ''Free to join, no caps, start today'', ''No caps · no limits'' in the program highlights, and ''No caps, no limits'' under its earnings estimator, so commission_cap is recorded as uncapped. The page cites a 100k+ fan community, which is a customer audience figure, not an absolute creator count, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 17, 17, 12, 8, 3, '{"niche_fit": "Sea moss gels and mineral wellness are highly demonstrable, routine-friendly products for wellness and beauty-from-within creators, though narrower than core skincare or makeup.", "ugc_evidence": "A creator-native program: custom links and codes, done-for-you captions and brand assets, a live dashboard, posting goals, streaks and a leaderboard built around regular content.", "compensation": "10% starting commission on every order with an explicit no-cap statement on the brand''s own page \u2014 verified uncapped \u2014 plus rate growth and goal-based commission boosts.", "contact_access": "Application is on the brand''s own site and a business contact email is published on the program page.", "opportunity_availability": "Free and publicly open to apply; applications reviewed personally, usually approved within a day.", "credibility": "Operating brand with a real storefront, community events and a published contact email and phone number, but a young, single-product-line business."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Indie Lee', 'https://indielee.com', 'Clean skincare brand (cleansers, toners, serums and body care) whose affiliate program runs on the Impact network at 10% commission per sale, as listed in affiliate program directories. A second directory describes the offer as up to 10.5%, which reads as a ceiling rather than a base rate, so the Impact-listed 10% is recorded. No cap statement is published, so the cap stays unknown.', 'United States', 'published') returning id into bid;
