  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 11, 6, 7, 4, '{"niche_fit": "Clean, ingredient-led skincare is core material for skincare UGC \u2014 routines, empties and ingredient explainers.", "ugc_evidence": "A network-run affiliate program on Impact gives creators tracked links and standard publisher tools, though the brand publishes no creator-specific program page of its own.", "compensation": "10% per sale on Impact is a fair mid-range rate; no cap statement is published, so the cap is honestly unknown, and a second listing''s ''up to 10.5%'' is a ceiling.", "contact_access": "No public program email is published; contact runs through the Impact network application.", "opportunity_availability": "Open application through Impact, listed for all regions.", "credibility": "Long-established clean beauty brand with national retail presence and consistent directory listings across two sources."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Inna Organic', 'https://innaorganic.co', 'Taiwanese certified-organic skincare brand — Asia''s first brand dual-certified by COSMOS and EWG — known for organic sheet masks, face oils and sensitive-skin care. It runs its own Affiliate Program page on its own site and its program is listed on ShareASale at 15% commission per sale with a 30-day cookie. No cap statement is published, so the cap stays unknown.', 'Taiwan', 'published') returning id into bid;
