  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 11, 14, 11, 7, 4, '{"niche_fit": "Certified-organic sheet masks and sensitive-skin care are strong, visual skincare UGC material with a clear clean-beauty angle.", "ugc_evidence": "The brand maintains its own affiliate program page and a ShareASale listing, but publishes no creator-specific perks, gifting or content program details.", "compensation": "15% per sale is an above-average skincare rate; no cap statement is published, so the cap is honestly unknown.", "contact_access": "Own-site affiliate page plus a published customer service email on the brand''s own site.", "opportunity_availability": "Publicly listed application via ShareASale and the brand''s own affiliate page.", "credibility": "Dual COSMOS and EWG certification, operating since 2015 with international retail and press coverage; based in Taipei, Taiwan."}'::jsonb);
