  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.castlebaths.com/affiliate-faq.html', 'brand_site', 'commission_rate', 'The brand''s own FAQ publishes the structure: ''Castle Baths offers a base 10% commission for standard affiliates and tier commissions for super performing affiliates (those who produce high sales volume) for a maximum potential commission of 20%'', with a $50 minimum before the first payment. The 10% base is recorded; 20% is a tier ceiling. No earnings cap statement or absolute creator counts are published, so commission_cap and creator_saturation stay unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 10, 12, 6, 7, 3, '{"niche_fit": "Bath, body and spa products fit self-care and pamper-routine UGC well, though the niche is narrower than skincare or makeup.", "ugc_evidence": "A standard ShareASale affiliate program documented on the brand''s own FAQ page; no creator-specific content program or gifting is published.", "compensation": "10% base commission with published tiers up to 20% for high-volume affiliates is solid; no cap statement is published, so the cap is honestly unknown.", "contact_access": "Program details are on the brand''s own site; application runs through ShareASale and no public program email is published.", "opportunity_availability": "Open application through ShareASale with a published $50 payout threshold.", "credibility": "Long-running niche bath and spa retailer with its own detailed affiliate FAQ; a small brand, so reach is modest."}'::jsonb);
