  insert into public.brands (name, website, description, country, status) values ('Ranavat', 'https://www.ranavat.com', 'Ayurvedic luxury skincare brand inspired by Indian royal beauty rituals (hair and skin oils, serums and masques). Its affiliate program runs on ShareASale: one directory records 10% per sale with a 15-day cookie as the officially listed payout, while a second directory describes the offer as up to 5.25%. Because the two published figures conflict, commission_rate is recorded as null with the conflict documented. No cap statement is published.', 'United States', 'published') returning id into bid;
