  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 11, 8, 6, 7, 4, '{"niche_fit": "Ayurvedic ritual skincare and hair oiling are distinctive, story-rich material for skincare and hair UGC.", "ugc_evidence": "A network-run ShareASale program with tracked links; the brand''s luxury positioning is creator-friendly, but no creator-specific program page is published.", "compensation": "Published rates conflict (10% flat vs up to 5.25%), so the rate is recorded as null and compensation is scored down for the uncertainty; no cap statement is published.", "contact_access": "No public program email is published; contact runs through the ShareASale application.", "opportunity_availability": "Open application through ShareASale, listed for all regions.", "credibility": "Established prestige brand with major retail distribution and press; only the rate documentation is inconsistent."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Divi', 'https://www.diviofficial.com', 'Scalp and hair health brand (scalp serum and hair wellness products) running its own Affiliate Program page on its own site: open to content creators, hair stylists and fans, with commission on every sale, a welcome gift, a friends & family promo code and early access to launches. The brand''s own page does not publish a percentage; a directory describes the offer as up to 15%, which is a ceiling, so commission_rate is recorded as null. No cap statement is published.', 'United States', 'published') returning id into bid;
