  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 15, 8, 13, 8, 4, '{"niche_fit": "Scalp care and hair-growth routines are a fast-growing, highly visual corner of beauty UGC.", "ugc_evidence": "The brand''s own program explicitly recruits content creators alongside stylists and fans, with a welcome gift, promo codes and early access \u2014 real creator-facing structure.", "compensation": "Commission on every sale is promised but no percentage is published on the brand''s page, and the only directory figure is an ''up to 15%'' ceiling, so the rate is null and scored cautiously; cap unknown.", "contact_access": "Application and program details are on the brand''s own site; no separate program email is published.", "opportunity_availability": "Publicly open application on the brand''s own affiliate page.", "credibility": "Well-known DTC hair wellness brand with national retail presence and an established social following."}'::jsonb);
