  insert into public.brands (name, website, description, country, status) values ('Kora Organics', 'https://www.koraorganics.com', 'Certified-organic skincare brand founded by Miranda Kerr in Australia in 2006/2009 and sold in 30 countries. Affiliate directories record its program at a 5–8% commission range per sale, and a separate Australian listing cites up to 4%. Because only a range and a conflicting ceiling are published — never a single base rate — commission_rate is recorded as null. No cap statement is published.', 'Australia', 'published') returning id into bid;
