  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Kora Organics Affiliate Program', 'https://getlasso.co/affiliate/kora-organics/', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/kora-organics/', 'affiliate_directory', 'affiliate_program', 'Lasso''s Kora Organics listing records the affiliate program with commission of 5%–8% per sale — a range, not a single published base rate.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopper.com/partnerships/koraorganics-com-affiliate-program', 'affiliate_directory', 'commission_rate', 'Shopper''s Kora Organics AU listing instead cites ''up to 4%'' payout per sale. A 5–8% range in one directory and an up-to-4% ceiling in another cannot settle a single rate, so commission_rate is recorded as null. The brand''s official website is koraorganics.com (its US storefront is us.koraorganics.com). No source publishes an earnings cap statement or absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 12, 8, 5, 7, 5, '{"niche_fit": "Certified-organic, founder-led skincare with hero products (Noni Glow, turmeric range) is premium skincare UGC material.", "ugc_evidence": "The program is carried in affiliate directories with standard tracked links; the brand itself is heavily creator- and founder-content driven, though no public creator program page is published.", "compensation": "Only a rate range and a conflicting regional ceiling are published, so the rate is recorded as null and compensation scored cautiously; cap unknown.", "contact_access": "No public affiliate program email is published; access runs through the network listing.", "opportunity_availability": "Listed as openly joinable through affiliate directories.", "credibility": "Global certified-organic brand founded by Miranda Kerr, sold in 30 countries with extensive press \u2014 credibility is not the issue, rate documentation is."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Loved01', 'https://loved01.com', 'Unisex skincare brand founded by John Legend (2023), formulated with dermatologist Dr. Naana Boakye for melanin-rich skin, priced at $10–15 and sold at CVS and Walmart. Affiliate directories record its program at up to 10.5% commission — an ''up to'' ceiling with no published base rate — so commission_rate is recorded as null. No cap statement is published.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Affiliate network (directory-listed)', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://getlasso.co/affiliate/loved01/.', 'https://getlasso.co/affiliate/loved01/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Loved01 Affiliate Program', 'https://getlasso.co/affiliate/loved01/', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/loved01/', 'affiliate_directory', 'affiliate_program', 'Lasso''s Loved01 listing records the affiliate program in the Beauty category with commission described as ''Up to 10.5%'', a 14-day cookie and no approval requirements.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.prnewswire.com/news-releases/john-legend-announces-loved01---affordable-skincare-for-melanin-rich-skin-301721926.html', 'press', 'commission_rate', 'The brand''s launch release confirms Loved01 as John Legend''s dermatologist-formulated skincare line for melanin-rich skin, priced $10–15 at loved01.com, CVS and Walmart. The only published commission figure is the directory''s ''up to 10.5%'' ceiling, so commission_rate is recorded as null. No source publishes an earnings cap statement or absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 11, 8, 5, 7, 4, '{"niche_fit": "Affordable, dermatologist-formulated skincare for melanin-rich skin fills a clear, underserved UGC niche.", "ugc_evidence": "A directory-listed affiliate program with tracked links; the celebrity-founded brand is social-first, but no public creator program page is published.", "compensation": "Only an ''up to 10.5%'' ceiling is published with no base rate, so the rate is recorded as null and compensation scored cautiously; cap unknown.", "contact_access": "No public program email is published; access runs through the network listing.", "opportunity_availability": "Directory-listed as open with no approval requirements.", "credibility": "Founded by John Legend with A-Frame Brands, national CVS and Walmart distribution and major press coverage since its 2023 launch."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Cincha Travel', 'https://www.cinchatravel.com', 'Oakland, California luggage-accessories brand whose flagship Travel Belt secures a personal bag to rolling luggage, freeing up travellers'' hands. Its affiliate program runs on Awin: the brand''s own merchant profile states a 15% commission per sale with a 30-day cookie, and says it aims to build an authentic community of partners who are passionate about the brand.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', 15, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/98075.', 'https://ui.awin.com/merchant-profile/98075', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Cincha Travel Affiliate Program (Awin)', 'https://ui.awin.com/merchant-profile/98075', 'https://ui.awin.com/merchant-profile/98075', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/98075', 'network_profile', 'affiliate_program', 'The brand''s own Awin merchant profile: ''Cincha Travel is a luggage accessories brand, based in Oakland, California... We aim to build an authentic community of partners who are passionate about our brand and give a 15% commission per sale (our average product cost is around $40-$75).'' Attribution period (cookie length) is 30 days. No earnings-cap statement is published, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/cincha-travel/', 'third_party_directory', 'affiliate_program', 'LinkClicky''s program listing independently reports Cincha Travel at 15% per sale with a 30-day cookie, and also references a ShareASale listing for the program; the Awin profile — the brand''s own current network profile — is the recorded route.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 17, 4, 8, 4, '{"compensation": "A brand-published 15% commission per sale on $40\u2013$75 average product prices with a 30-day cookie \u2014 a strong rate for travel accessories; no cap statement is published.", "contact_access": "No partnerships email is published on the Awin profile \u2014 joining is through the network application.", "credibility": "An established direct-to-consumer travel accessories brand with a category-defining flagship product, though smaller than the heritage luggage houses.", "niche_fit": "Travel belts and luggage accessories are natural packing-video, carry-on and travel-hack content for travel creators.", "opportunity_availability": "Open application through Awin with brand approval.", "ugc_evidence": "The Awin profile frames the program as building ''an authentic community of partners'' passionate about the brand, though it is a conventional affiliate profile rather than a structured UGC campaign track."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Int2Cruises', 'https://int2cruises.com', 'Asia''s cruise-first online travel platform, based in New Delhi, India, offering cruise vacations across 25+ international cruise lines and 300+ destinations. Its Creator Hub is an affiliate program built exclusively for travel and cruise content creators: 5% commission on the total cruise fare for every confirmed booking, a live earnings dashboard, and explicit no-cap earnings statements on the brand''s own program page — a verified-uncapped program.', 'India', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'marketing', 'marketing@int2cruises.com', null, 'https://int2cruises.com/affiliate-program', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 5, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://int2cruises.com/affiliate-program.', 'https://int2cruises.com/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Int2Cruises Creator Hub Affiliate Program', 'https://int2cruises.com/affiliate-program', 'https://int2cruises.com/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://int2cruises.com/affiliate-program', 'official_program_page', 'commission_cap', 'The brand''s own Creator Hub page states ''No cap. No ceiling.'' for commission on every booking, and its FAQ section states ''There is no limit to how much you can earn'' — an explicit no-cap earnings statement on the brand''s own page, so commission_cap is uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://int2cruises.com/affiliate-program', 'official_program_page', 'creator_program', 'Program mechanics from the same page: ''You earn 5% commission on the fare — tracked live, paid transparently''; free to join with no registration fees; applications reviewed within 2–3 business days; no minimum follower count — ''Int2Cruises focuses on content quality and audience engagement rather than follower count alone''; commissions paid via direct bank transfer after a confirmed booking; queries to marketing@int2cruises.com. Top performers can unlock free cruise (barter) collaborations.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 18, 14, 11, 9, 3, '{"compensation": "5% of the total cruise fare with an explicit ''No cap. No ceiling.'' statement \u2014 verified-uncapped; cruise fares are high-value, so per-booking commissions run from tens to hundreds of dollars, though the percentage itself is modest.", "contact_access": "A published program email (marketing@int2cruises.com) and phone number appear directly on the Creator Hub page.", "credibility": "A young, India-based cruise platform rather than an established global OTA; terms are clearly published, but the brand is little-known outside its home market.", "niche_fit": "Cruise vacations are a growing travel-creator niche \u2014 ship tours, itinerary vlogs and booking tips \u2014 though narrower than general travel gear.", "opportunity_availability": "Free to join, no minimum follower count, applications reviewed within 2\u20133 business days.", "ugc_evidence": "A creator-only program by design: the page addresses social media creators, travel bloggers, podcasters and community hosts by name, with a personalised link and promo code issued on approval."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('On', 'https://www.on.com', 'Swiss performance sportswear brand founded in Zurich in 2010, known for CloudTec cushioning across running, outdoor, training and lifestyle footwear and apparel. Its affiliate program runs on Awin: the brand''s own merchant profile publishes tiered commission rates ranging from 2%–20% depending on product seasonality and partner type, with a 30-day cookie — a range rather than a single rate, so no single rate is recorded.', 'Switzerland', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/124262.', 'https://ui.awin.com/merchant-profile/124262', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'On Affiliate Program (Awin)', 'https://ui.awin.com/merchant-profile/124262', 'https://ui.awin.com/merchant-profile/124262', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/124262', 'network_profile', 'affiliate_program', 'The brand''s own Awin merchant profile (On.com CA): ''Commission rates range from 2%–20%, with tiered commissioning applied based on product seasonality (full-price vs last season items) and partner type; Cookie window: 30 days; Validation period: 30 days.'' Preferred partners include ''Product reviewers and gear experts'', ''Sneaker and streetwear culture platforms'' and ''Creators/influencers''. Because the brand publishes a tiered range rather than a single rate, commission_rate is null. No earnings-cap statement is published, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/124262', 'network_profile', 'opportunity_availability', 'The same profile carries an availability caveat: ''Only previously approved partners who were part of our existing affiliate program will be eligible for approval at this time. Due to the volume of applications, no new publishers will be approved until April 1st, 2026.'' New-publisher approvals were paused under that notice, which is scored into opportunity_availability.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 16, 10, 5, 5, 5, '{"compensation": "The brand publishes only a tiered 2%\u201320% range (seasonality and partner type), so no single rate can be recorded and compensation scores cautiously; no cap statement is published.", "contact_access": "No partnerships email is published on the fetched Awin profile \u2014 contact is through the network application.", "credibility": "One of the world''s fastest-growing performance footwear brands, a global leader in innovative running shoes and apparel.", "niche_fit": "Running and training footwear is core content for running, fitness and sneaker creators \u2014 reviews, rotations and race-day content.", "opportunity_availability": "The profile''s own notice paused new-publisher approvals (previously approved partners only, until April 1st, 2026), so availability is scored down.", "ugc_evidence": "The Awin profile names creators/influencers among its preferred partner types and offers priority access to exclusive drops and campaigns for partners."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Under Armour', 'https://www.underarmour.com', 'American performance apparel, footwear and accessories giant founded in 1996 — HeatGear, ColdGear, running shoes and connected fitness gear. Its US affiliate program runs on Awin: the brand''s own merchant profile publishes a 5% commission with a 30-day cookie, in-app tracking and a $100 average order size.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', 5, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/15431?setLocale=pl_PL.', 'https://ui.awin.com/merchant-profile/15431?setLocale=pl_PL', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Under Armour Affiliate Program (Awin US)', 'https://ui.awin.com/merchant-profile/15431?setLocale=pl_PL', 'https://ui.awin.com/merchant-profile/15431?setLocale=pl_PL', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/15431?setLocale=pl_PL', 'network_profile', 'affiliate_program', 'The brand''s own Awin merchant profile (Under Armour US): ''5% commission, 30 day cookie; Average order size: $100; In-app tracking and the ability to earn commission on app sales; Comprehensive data feed, updated daily; Banner and text creative, updated monthly; Cross device tracking.'' No earnings-cap statement is published, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.awin.com/us/news-and-events/program-news/advertiser-spotlight-under-armour', 'network_announcement', 'affiliate_program', 'Awin''s own program spotlight confirms the structure: ''Publishers joined to the Under Armour program can receive up to 5% commission (portion of revenue) from completed sales across the web and the Under Armour app, on both Android & iOs devices, within a 30-day cookie window'', with average order size of $100 USD and in-app and cross-device tracking enabled.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 12, 11, 5, 8, 5, '{"compensation": "A brand-published 5% commission on a $100 average order size with in-app tracking \u2014 a modest percentage on premium prices; no cap statement is published.", "contact_access": "No partnerships email is published on the fetched Awin profile \u2014 the profile offers team support for custom creative requests after joining.", "credibility": "One of the world''s largest performance sportswear brands, founded in 1996.", "niche_fit": "Performance apparel and footwear span running, training, team sports and outdoor content \u2014 among the most-covered categories in fitness creator feeds.", "opportunity_availability": "Open application through Awin with brand approval; daily data feed and monthly creative provided.", "ugc_evidence": "A conventional network affiliate program with monthly creative updates and a partnership-approach support team; no dedicated creator or UGC track is evidenced on the profile."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('ASICS', 'https://www.asics.com', 'Japanese performance sportswear giant founded in 1949 — Gel-Kayano, Gel-Nimbus and Novablast running shoes plus training, tennis and trail gear. Its US affiliate program runs on Rakuten Advertising; published rates conflict across sources (3% via the Rakuten listing versus 6% in running-program roundups), so no rate is recorded.', 'Japan', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Rakuten Advertising', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://linkclicky.com/affiliate-program/asics/.', 'https://linkclicky.com/affiliate-program/asics/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'ASICS Affiliate Program (Rakuten Advertising)', 'https://linkclicky.com/affiliate-program/asics/', 'https://linkclicky.com/affiliate-program/asics/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/asics/', 'third_party_directory', 'affiliate_program', 'LinkClicky''s program listing places ASICS on Rakuten Advertising (US region) at ''3% per sale'', with sign-up routed through Rakuten''s publisher signup (signup.linkshare.com). No earnings-cap statement is published, so commission_cap is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://uppromote.com/affiliate-programs/running/', 'third_party_directory', 'commission_rate_conflict', 'Published rates conflict: UpPromote''s running affiliate roundup and Tapfiliate''s fitness roundup both report ASICS at 6% commission with a 30-day cookie, against LinkClicky''s 3% on Rakuten Advertising. Because the figures conflict across sources and the brand publishes no rate on a fetched brand page, commission_rate is null.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 11, 8, 4, 7, 5, '{"compensation": "Published figures conflict (3% via Rakuten per LinkClicky versus 6% in roundups) and the brand publishes no rate on a fetched page, so no rate is recorded and compensation scores low; no cap statement is published.", "contact_access": "No partnerships email is published in the fetched sources \u2014 joining is through the Rakuten application.", "credibility": "One of the world''s leading performance running brands, founded in Japan in 1949.", "niche_fit": "Running shoes are evergreen core content for running and fitness creators \u2014 reviews, shoe rotations and marathon training.", "opportunity_availability": "Apply through Rakuten Advertising with brand approval; US program per the directory listing.", "ugc_evidence": "A conventional network affiliate program; no dedicated creator or UGC track is evidenced in the fetched sources."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('adidas', 'https://www.adidas.com', 'German sportswear giant founded in 1949 — running, football, training and lifestyle icons from Ultraboost to Samba and Gazelle. Its US affiliate program runs on Impact and has since 2016: adidas does not publish a public rate table (exact rates appear in the dashboard after approval); network listings commonly show up to 10% with lower rates on hero sneaker lines, so no rate is recorded.', 'Germany', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://reverbico.com/blog/adidas-affiliate-program/.', 'https://reverbico.com/blog/adidas-affiliate-program/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'adidas Affiliate Program (Impact US)', 'https://reverbico.com/blog/adidas-affiliate-program/', 'https://reverbico.com/blog/adidas-affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://reverbico.com/blog/adidas-affiliate-program/', 'third_party_directory', 'affiliate_program', 'A detailed program guide (updated November 18, 2026) confirms: ''In the US it runs on impact.com... adidas does not publish a public rate table, but its commission is commonly listed at up to 10%, with lower rates on some best-selling sneakers, and a 30-day cookie. You apply free through adidas''s affiliate page, which sends you to Impact.'' Applications are reviewed manually by adidas; regional programs run on other networks (Rakuten in MENA, Partnerize in Europe). No earnings-cap statement is published, so commission_cap is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://reverbico.com/blog/adidas-affiliate-program/', 'third_party_directory', 'commission_rate_conflict', 'The most detailed recent listing (via Skimlinks, quoted in the same guide) shows 10% on qualifying sales but 5% on Gazelle, Samba, Spezial and Evo SL, and 0% on gift cards and selected limited editions, with rates varying by country and product line. Because adidas itself publishes no rate and figures vary by line and region, commission_rate is null.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 13, 10, 5, 7, 5, '{"compensation": "adidas publishes no public rate; listings commonly show up to 10% but only 5% on its most talked-about sneaker lines and 0% on gift cards, so no rate is recorded; no cap statement is published.", "contact_access": "No partnerships email is published in the fetched sources \u2014 contact is through the Impact application and dashboard.", "credibility": "One of the two largest sportswear brands in the world, founded in 1949.", "niche_fit": "Running, football, training and lifestyle sneakers sit at the centre of sports, fitness and streetwear creator content.", "opportunity_availability": "Free application via adidas''s affiliate page into Impact, with manual review by adidas; US program, with separate regional programs elsewhere.", "ugc_evidence": "A conventional network affiliate program open to sites and channels; adidas''s separate creator/ambassador deals are arranged directly with no public application, per the fetched guide."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Quay Australia', 'https://www.quayaustralia.com', 'Australian-born eyewear brand founded in Melbourne in 2004, known for trend-led, affordable sunglasses sold worldwide. Its affiliate program runs on CJ Affiliate: directories consistently report 8% per sale with a 30-day cookie, and the program is pitched squarely at influencers and eyewear/fashion publishers.', 'Australia', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'CJ Affiliate', 8, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://getlasso.co/affiliate/quay-australia/.', 'https://getlasso.co/affiliate/quay-australia/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Quay Australia Affiliate Program (CJ Affiliate)', 'https://getlasso.co/affiliate/quay-australia/', 'https://getlasso.co/affiliate/quay-australia/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/quay-australia/', 'third_party_directory', 'affiliate_program', 'Lasso''s program listing reports the Quay Australia affiliate program at ''8% Per Sale'' with a ''30 Day'' cookie, and its join link routes to CJ Affiliate publisher sign-up (signup.cj.com). The listing frames the program as an opportunity ''for influencers and marketers alike''. No earnings-cap statement is published, so commission_cap is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/quay/', 'third_party_directory', 'affiliate_program', 'LinkClicky''s listing independently agrees: affiliate platform CJ Affiliate, US region, ''Commission: 8% per sale'' for Quay. Two directories agree on the network and the rate, so 8% is recorded.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 14, 4, 7, 4, '{"compensation": "8% per sale with a 30-day cookie, consistently reported by two directories for the CJ program \u2014 a solid rate on affordable, high-turnover eyewear; no cap statement is published.", "contact_access": "No partnerships email is published in the fetched sources \u2014 joining is through the CJ application.", "credibility": "A well-known global eyewear brand founded in Melbourne in 2004, though smaller than the fashion majors.", "niche_fit": "Affordable trend sunglasses are staple fashion-accessory content \u2014 outfit styling, festival looks and seasonal hauls.", "opportunity_availability": "Apply through CJ Affiliate with brand approval; US region per the directory listing.", "ugc_evidence": "The program is marketed to influencers as well as publishers in the directory listings, though no structured UGC campaign track is evidenced on a fetched brand page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Unique Vintage', 'https://www.uniquevintage.com', 'Vintage-inspired fashion retailer — retro dresses, swim, Halloween and pop-culture collections in inclusive sizing. Its North America affiliate program runs on Awin: the program''s own Awin terms set standard commission at 4% on new customers and 2% on returning customers, and its allowed partner types explicitly include content creators, influencers and UGC communities. Because the standard rate splits by customer type, no single rate is recorded.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/advertiser-terms/123224/period.', 'https://ui.awin.com/advertiser-terms/123224/period', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Unique Vintage Affiliate Program (Awin North America)', 'https://ui.awin.com/advertiser-terms/123224/period', 'https://ui.awin.com/advertiser-terms/123224/period', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/advertiser-terms/123224/period', 'network_terms', 'affiliate_program', 'The program''s own Awin terms and conditions (Unique Vintage - North America, last updated 23 Jul 2026): ''Standard commission is 4% New Customers / 2% Returning Customers on qualifying sales tracked through Awin.'' Participation is subject to approval through Awin; commissions are paid through Awin and may be reversed for returns, cancellations or unauthorized coupon use (orders using unauthorized coupons earn $0). Because the standard commission splits by customer type rather than publishing one rate, commission_rate is null. No earnings-cap statement is published, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/advertiser-terms/123224/period', 'network_terms', 'creator_program', 'The same Awin terms list allowed partner types including ''Social traffic'', ''Communities and UGC'' and ''Content creators and influencers'', with FTC-compliant content required — direct evidence the program accepts creator and UGC partners, not just coupon sites.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 15, 8, 4, 7, 4, '{"compensation": "Standard commission is 4% on new customers and 2% on returning customers per the program''s own terms \u2014 modest rates that split by customer type, so no single rate is recorded; no cap statement is published.", "contact_access": "No partnerships email is published in the fetched terms \u2014 joining is through the Awin application.", "credibility": "An established niche fashion retailer with a long-running affiliate presence on Awin, though far smaller than national apparel chains.", "niche_fit": "Vintage-inspired dresses, retro swim and Halloween collections map to pin-up, retro-styling and seasonal fashion creator niches.", "opportunity_availability": "Apply through Awin with brand approval; coupon/deal partners require prior written approval.", "ugc_evidence": "The program''s own Awin terms explicitly allow ''Communities and UGC'' and ''Content creators and influencers'' as partner types \u2014 direct creator-program evidence."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('AllTrails', 'https://www.alltrails.com', 'The world''s most-used trail discovery platform — 200,000+ hand-curated trail maps for hiking, running and mountain biking, with Plus and Peak subscription tiers. Its affiliate program runs on Impact: partners earn commission when readers upgrade to Plus or Peak, with published payouts of 10% per subscription purchase plus flat $1 payments per registration, free trial and gift purchase.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.alltrails.com/affiliates.', 'https://www.alltrails.com/affiliates', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'AllTrails Affiliate Program (Impact)', 'https://www.alltrails.com/affiliates', 'https://www.alltrails.com/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.alltrails.com/affiliates', 'official_program_page', 'creator_program', 'AllTrails'' official affiliates page: ''AllTrails affiliates spread the stoke. Tell us how you inspire people to find their way outdoors and earn a commission in return.'' Partners promote ''AllTrails, Plus, and Peak through articles, newsletters, ads, social media, and more'' and ''every time someone upgrades to Plus or Peak by clicking your unique link, you''ll receive a commission''. The brand publishes no rate on this page. No earnings-cap statement is published, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/alltrails/', 'third_party_directory', 'affiliate_program', 'LinkClicky''s listing places the AllTrails affiliate program on Impact (all regions) with published payouts: ''$1 per registration, $1 per free trial, 10% per subscription purchase, $1 per gift purchase''. The 10% subscription rate is recorded as commission_rate; the $1 payments are flat per-action fees documented here.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 15, 13, 5, 7, 5, '{"compensation": "10% per subscription purchase plus flat $1 per registration, free trial and gift purchase (per the Impact listing) \u2014 a modest ticket size, but upgrades are a natural, high-intent conversion; no cap statement is published.", "contact_access": "No partnerships email is published on the official page \u2014 application is through the page and Impact.", "credibility": "The most trusted and used outdoors platform in the world, with hundreds of thousands of curated trails and a community of millions.", "niche_fit": "Trail guides, hiking itineraries and outdoor trip content are staples for travel and outdoor creators, and the app is the default tool their audiences already use.", "opportunity_availability": "Apply via the official affiliates page / Impact; the brand reviews fit (''If you''re a program match, we''ll reach out''), so approval is selective.", "ugc_evidence": "The official affiliates page recruits partners who ''inspire people to find their way outdoors'' and names social media among the promotion channels \u2014 clear creator-facing positioning."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('VisitorsCoverage', 'https://www.visitorscoverage.com', 'Pioneer online travel insurance marketplace founded in 2006 and based in Santa Clara, California, letting travellers in 175+ countries compare and buy visitors insurance and trip cancellation plans. Its own Partner Program pays referral fees based on the price of the policy sold — published tiers run from $1 to $100 per sale — with an Elite Partner level for higher fees. Because the fees are flat per-sale amounts rather than a percentage, no rate is recorded.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.visitorscoverage.com/partner/faq/.', 'https://www.visitorscoverage.com/partner/faq/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'VisitorsCoverage Partner Program', 'https://www.visitorscoverage.com/partner/faq/', 'https://www.visitorscoverage.com/partner/faq/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.visitorscoverage.com/partner/faq/', 'official_program_page', 'affiliate_program', 'The brand''s own partner FAQ: ''The VisitorsCoverage Partner Program allows you to earn referral fees when your client purchases an insurance policy through your unique link, banner or widget... Referral fees are based on the price of the policy sold... Partners who apply through our online form will be eligible to reach an Elite Partner level which allows for higher fees.'' Joining is free, no licence is required, the program is available worldwide, and partners are paid monthly once the balance reaches $100. The brand publishes no percentage and no earnings-cap statement, so commission_rate is null and commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.travelpayouts.com/blog/the-visitorscoverage-affiliate-program/', 'third_party_directory', 'affiliate_program', 'Travelpayouts'' program page documents the flat fee table: policy $10–$49.99 pays $1; $50–$199.99 pays $5; $200–$599.99 pays $20; $600–$1,999.99 pays $60; $2,000+ pays $100, with a 30-day cookie — flat per-sale referral fees (described as up to ~10% of policy price), not a percentage rate.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 10, 11, 6, 8, 4, '{"compensation": "Flat referral fees of $1\u2013$100 per sale scaled to policy price (documented tiers), with an Elite Partner level for higher fees \u2014 real money on high-value policies, but no percentage rate exists to record; no cap statement is published.", "contact_access": "The brand runs its own partner portal and reviews applications, but no partnerships email is published on the fetched FAQ page.", "credibility": "A pioneer insurtech marketplace operating since 2006, serving travellers in 175+ countries from its Santa Clara base.", "niche_fit": "Travel insurance is a standard recommendation in travel-creator content \u2014 visa, backpacking and family-trip planning especially \u2014 though it is a utility purchase rather than a lifestyle product.", "opportunity_availability": "Free to join, no insurance licence required, available worldwide, with approval through the brand''s online form.", "ugc_evidence": "A partner/referral program aimed at websites and businesses with links, banners and widgets; no dedicated creator track is evidenced, though travel bloggers are its natural partners."}'::jsonb);
