  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://forceofnature.com/pages/faq', 'brand_website', 'affiliate_program', 'Force of Nature''s own FAQ states: ''We do have an affiliate program! Our program offers a 10% affiliate commission'', with onboarding routed through an app.impact.com sign-up link. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 13, 12, 6, 8, 5, '{"niche_fit": "Regenerative grass-fed meats are a strong fit for food, homestead, carnivore and wellness creators.", "ugc_evidence": "The brand runs a formal affiliate program through Impact with a published commission, open to promoters.", "compensation": "10% commission published on the brand''s own FAQ; no cap statement published, so the cap is honestly unknown.", "contact_access": "Application runs through the brand FAQ''s Impact link; no public partnerships email was published on the fetched page.", "opportunity_availability": "Program is live and joinable now via Impact.", "credibility": "Established regenerative-meat brand with a transparent sourcing story and a long-running direct-to-consumer store."}'::jsonb);
