  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://coffeebros.com/pages/coffee-affiliate-program', 'brand_website', 'affiliate_program', 'Coffee Bros.'' own affiliate page publishes 10% standard / 15% VIP commission on coffee, 6% standard / 10% VIP on equipment, plus referral bonuses rising to 25% at 200 referred customers; the program runs through Impact.com. The standard coffee rate of 10% is recorded. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
