  insert into public.brands (name, website, description, country, status) values ('Joy Organics', 'https://joyorganics.com', 'Joy Organics makes USDA-organic, THC-free CBD oils, gummies, softgels and topicals, and runs an affiliate program through ShareASale reported at a high 25% commission; the program is US-focused and does not accept coupon or cashback publishers.', 'United States', 'published') returning id into bid;
