  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Joy Organics Affiliate Program (ShareASale)', 'https://getlasso.co/affiliate/joy-organics/', 'https://getlasso.co/affiliate/joy-organics/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/joy-organics/', 'affiliate_directory', 'affiliate_program', 'Lasso''s Joy Organics program page reports a 25% per-sale commission through ShareASale with a 90-day cookie. Multiple independent affiliate directories (AffRoom, AffTank, UpPromote, Tapfiliate) consistently report the same 25% ShareASale rate; cookie reports conflict across sources (30 days vs 90 days vs longer), so only the consistently reported 25% rate is recorded and the cookie is not relied on. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 12, 18, 5, 8, 4, '{"niche_fit": "Organic CBD for sleep, calm and recovery is a proven wellness-creator topic, though CBD promotion carries platform restrictions.", "ugc_evidence": "A formal ShareASale affiliate program is consistently reported across multiple directories; the brand''s own program page was not directly fetched, so evidence is publicly reported rather than verified.", "compensation": "25% commission consistently reported by five independent sources; no cap statement published, so the cap is unknown.", "contact_access": "Application runs through ShareASale; no public partnerships email was verified from a fetched page.", "opportunity_availability": "Program is open now via ShareASale; US-focused and coupon/cashback publishers are excluded.", "credibility": "USDA-organic certified CBD brand with third-party lab testing and an established retail presence."}'::jsonb);
