  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.timeline.com/pages/affiliate-program', 'brand_website', 'affiliate_program', 'Timeline''s own affiliate page runs two routes: a Creator Affiliate Program for individual creators/influencers (paid monthly via PayPal) and an Impact Affiliate Program for publishers (paid via Impact.com). Its FAQ states applicants must be 18+ with an active audience in the US, France, Switzerland, UK, Germany or Canada, decisions are emailed within seven business days, posts must carry #timelinepartner, and questions go to affiliates@timeline.com. No commission percentage is published on the page, so commission_rate is null. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 15, 6, 12, 8, 5, '{"niche_fit": "Longevity and Urolithin A are high-interest topics for health-optimization and biohacking creators.", "ugc_evidence": "The brand runs a dedicated Creator Affiliate Program for social creators alongside its Impact publisher program, with a published FAQ and disclosure hashtag.", "compensation": "No commission percentage is published on the brand''s program page, so the rate is honestly null and compensation scores low.", "contact_access": "A dedicated affiliates@timeline.com contact is published in the program FAQ on the brand''s own page.", "opportunity_availability": "Program is open now in six countries with decisions promised within seven business days.", "credibility": "18+ years of longevity research with randomized double-blind human clinical trials cited on the brand''s own pages."}'::jsonb);
