  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Lazarus Naturals Affiliate Partner Program', 'https://www.lazarusnaturals.com/pages/affiliates', 'https://www.lazarusnaturals.com/pages/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.lazarusnaturals.com/pages/affiliates', 'brand_website', 'affiliate_program', 'Lazarus Naturals'' own affiliates page confirms its Affiliate Partner Program — free to join, approval on a case-by-case basis — but publishes no percentage (''Typically you earn a percentage of each sale''). Third-party rates conflict (LinkClicky reports 2%-15% via Impact; Shopper reports roughly 1.33-9.97%), so commission_rate is null with the conflict documented here. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 12, 5, 5, 7, 5, '{"niche_fit": "Farm-to-shelf CBD fits wellness creators, though CBD promotion carries platform restrictions.", "ugc_evidence": "The brand runs a formal Affiliate Partner Program confirmed on its own page, with case-by-case approval.", "compensation": "No rate is published by the brand and third-party figures conflict (2%-15% vs ~1.3-10%), so the rate is honestly null.", "contact_access": "Application runs through the brand''s own affiliates page; no usable public email was visible on the fetched page.", "opportunity_availability": "Program is open now and free to join, subject to case-by-case approval.", "credibility": "Vertically integrated farm-to-shelf producer with third-party testing and a long-running assistance program for veterans and low-income customers."}'::jsonb);
