  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Gaia Herbs Affiliate Program', 'https://www.gaiaherbs.com/pages/gaia-herbs-affiliate-terms-and-conditions', 'https://www.gaiaherbs.com/pages/gaia-herbs-affiliate-terms-and-conditions', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.gaiaherbs.com/pages/gaia-herbs-affiliate-terms-and-conditions', 'brand_website', 'affiliate_program', 'Gaia Herbs'' own Affiliate Program Terms and Conditions (effective February 25, 2026) confirm a formal program: affiliates must be 18+ US legal residents, promote only through Approved Promotion Locations named in a Project Brief, follow FTC disclosure rules, and work under an individual Service Agreement. Compensation is set per Service Agreement/Project Brief and is not published; third-party figures conflict (about 2%, 3.39%, and 1-4% ranges), so commission_rate is null. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 5, 5, 6, 5, '{"niche_fit": "Herbal adaptogens and stress/immune formulas are staple wellness-creator topics.", "ugc_evidence": "The brand''s own published program terms describe a structured creator program with Project Briefs, approved promotion locations and content rules.", "compensation": "Pay is set per individual Service Agreement and never published, with conflicting third-party figures, so the rate is honestly null.", "contact_access": "No public application email was published in the fetched terms; entry runs through the brand''s program/representative.", "opportunity_availability": "Program exists and is governed by current (2026) terms, but entry is brief-based and US-only rather than open self-serve.", "credibility": "One of the longest-established US herbal brands, with published program terms and formal FTC compliance requirements."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('My SuperHero Foods', 'https://mysuperherofoods.com', 'My SuperHero Foods teaches kids about real, whole foods through its rhyming children''s book and food-education products, and runs the SuperHero Friends affiliate program for parents, teachers and mom creators — no minimum audience required.', 'United States', 'published') returning id into bid;
