  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://mysuperherofoods.com/affiliate-program/.', 'https://mysuperherofoods.com/affiliate-program/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'SuperHero Friends Affiliate Program', 'https://mysuperherofoods.com/affiliate-program/', 'https://mysuperherofoods.com/affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://mysuperherofoods.com/affiliate-program/', 'brand_website', 'affiliate_program', 'My SuperHero Foods'' own affiliate page publishes the SuperHero Friends tiers: Tier 1 gives a 15%-off audience code and link; Tier 2 (after the first order) pays 10% commission on all sales; Tier 3 (25 orders) pays 15% on physical and 25% on digital products; Tier 4 (150 orders) pays 20% physical / 30% digital plus a $100 reward. Creators with 10K+ followers start at Tier 3, but no audience minimum is required. Applicants must be US-based businesses with a public social account; payments are monthly at a $50 balance, and the contact hi@mysuperherofoods.com is printed on the page. The entry paid rate of 10% is recorded. No earnings-cap statement is published, so commission_cap is unknown; openness to small creators is not an absolute creator count, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 21, 15, 12, 12, 8, 4, '{"niche_fit": "Kids'' food education fits parent, teacher and family-food creators \u2014 a defined niche rather than general food.", "ugc_evidence": "The brand runs a formal tiered affiliate program explicitly recruiting parents, teachers, bloggers and creators of any audience size.", "compensation": "10% commission from the first order, rising to 20% physical / 30% digital at the top tier; no cap statement, so the cap is unknown.", "contact_access": "A contact email (hi@mysuperherofoods.com) is printed on the brand''s own affiliate page.", "opportunity_availability": "Program is open now with no audience minimum; applicants must be US-based businesses.", "credibility": "Published program terms since 2022 with endorsements from named nutrition professionals on its own page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Glass Aqua', 'https://shop.glassaqua.com', 'Online retailer of planted-aquarium and aquascaping supplies — tanks, lighting, plants and gear from brands such as Ultum Nature Systems — sold through its own Shopify storefront. It runs its own affiliate program paying 5% on every sale, with a higher VIP tier, and its program page states there is no cap on how much can be earned.', 'United States', 'published') returning id into bid;
