  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Glass Aqua Affiliate Program — 5% on every sale, VERIFIED UNCAPPED (''no cap on how much can be earned'' on the brand''s own page), instant approval', 'https://shop.glassaqua.com/pages/join-affiliate-program', 'https://shop.glassaqua.com/pages/join-affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://shop.glassaqua.com/pages/join-affiliate-program', 'official_site', 'affiliate', 'Glass Aqua''s own affiliate program page fetched in full: ''earn 5% on every sale you bring in. The sky is the limit with no cap on how much can be earned.'' That explicit no-cap statement on the brand''s own program page makes the commission cap UNCAPPED. The page also states a VIP affiliate tier with a higher percentage is available, commission is paid monthly, and the cookie duration is 30 days.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://shop.glassaqua.com/pages/join-affiliate-program', 'official_site', 'affiliate', 'The same official page states joining is free and ''Approval is instant'' with access to an affiliate dashboard, earnings and traffic reports at any time, and that anyone may join (accounts can be terminated for inappropriate content). Applications are taken by email with social media platforms and/or website links, or via the on-site sign-up.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 12, 14, 9, 9, 4, '{"niche_fit": "Planted-aquarium and aquascaping gear is a visual, hobbyist niche with strong before/after content potential, though narrower than mainstream pet", "ugc_evidence": "A standing affiliate program with an instant-approval dashboard; no dedicated creator or UGC programme is published", "compensation": "Verified uncapped on the brand''s own page, but the base rate is a modest 5% (higher VIP tier unpublished)", "contact_access": "Application is via the program page sign-up or an email application; no direct affiliate email address is published", "opportunity_availability": "Open to anyone with instant approval \u2014 among the lowest-friction entries in this batch", "credibility": "Retailer claims more than 15 years in the industry on its own page; established specialist aquatics storefront"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('FreePet', 'https://freepetus.com', 'Maker of welded-steel dog crates and playpens with a 10-year warranty, sold direct through freepetus.com. Its own affiliate program pays tiered commission — 8% starting, 12% at the Creator tier and 15% at the Partner tier — with no minimum audience size, a 60–90 day cookie and monthly payouts.', 'United States', 'published') returning id into bid;
