  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 8, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://freepetus.com/pages/affiliate.', 'https://freepetus.com/pages/affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'FreePet Affiliate Program — tiered 8%/12%/15% commission on steel dog crates and playpens, no minimum audience, via the brand''s own program (payouts via PayPal, bank transfer or Shopify Collabs)', 'https://freepetus.com/pages/affiliate', 'https://freepetus.com/pages/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://freepetus.com/pages/affiliate', 'official_site', 'affiliate', 'FreePet''s official affiliate page fetched in full: commission tiers are 8% on the first $5,000 of monthly net sales, 12% from $5,000–$15,000 and 15% above $15,000, auto-upgraded monthly; cookies run 60 days at Starter and 90 days at Creator/Partner tiers; average order value is stated as $120; payouts land on the 15th monthly with a $50 minimum via PayPal, bank transfer or Shopify Collabs. No earnings-cap statement is published, so the cap is unknown; the recorded rate is the 8% starting tier.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://freepetus.com/pages/affiliate', 'official_site', 'creator_program', 'The same page is explicitly creator-facing: it names YouTube and TikTok creators, dog blogs and review sites as target partners, states ''No hard minimum'' audience size (''We review each application by content quality and audience fit, not follower count''), offers a full asset library (200+ photos, 4K clips, banners), custom discount codes at Creator tier and co-marketing/IG collabs at Partner tier, with approval typically within 3 business days.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 16, 13, 11, 9, 4, '{"niche_fit": "Steel dog crates and playpens are demonstrable, review-friendly pet products with a clear unboxing and durability story", "ugc_evidence": "A dedicated partner program courting YouTube/TikTok creators and review blogs, with a large cleared asset library and co-marketing at the top tier", "compensation": "Tiered 8% rising to 15% on a $120 average order is solid mid-range pay; no cap statement is published, so the cap stays unknown", "contact_access": "Application form on the official page with a promised dedicated partner contact and 24-hour email response; no public email address", "opportunity_availability": "No minimum audience and approval within about 3 business days \u2014 very accessible", "credibility": "Brand cites 28 years of manufacturing, a 4.9-star average and 6,200 homes on its own page"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('A Pup Above', 'https://apupabove.com', 'Austin, Texas maker of gently cooked, sous-vide fresh dog food from 100% human-grade, non-GMO ingredients, sold by subscription through apupabove.com. Its affiliate program runs on Impact and is widely reported to pay a flat $60 per online sale or 5% recurring commission on subscriptions.', 'United States', 'published') returning id into bid;
