  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'contact@apupabove.com', 'https://apupabove.com/pages/affiliate', 'https://apupabove.com/pages/affiliate', 'verified', now());
