  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'A Pup Above Affiliate Program — flat $60 per sale or 5% recurring on subscriptions (reported), via Impact; apply from the brand''s affiliate page', 'https://apupabove.com/pages/affiliate', 'https://apupabove.com/pages/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://apupabove.com/pages/affiliate', 'official_site', 'affiliate', 'A Pup Above''s official affiliate page fetched in full: it publishes no rate itself and directs applicants to apply through Impact (''To apply and learn more about our affiliate program, please go here'' linking to app.impact.com). The page publishes the brand contact email contact@apupabove.com and states the brand was founded in Austin, TX.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://olavivo.com/dog-affiliate-programs/', 'listing', 'affiliate', 'Multiple affiliate roundups agree on the structure: $60 flat per online sale or 5% recurring commission on subscriptions, on the Impact network, with 30-day (flat) and 45-day (subscription) cookies — reported consistently by Olavivo, LinkClicky and Meer''s World. One source (Creator Hero) reports $25–$40 per sale instead, so the flat figure varies by source; because a percentage is also published, commission_rate records the 5% recurring rate with the flat bounty documented here. No earnings-cap statement is published anywhere found, so the cap is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 15, 12, 7, 5, '{"niche_fit": "Fresh sous-vide dog food is a premium, highly demonstrable subscription product squarely in the pet UGC sweet spot", "ugc_evidence": "An established network program on Impact aimed at creators, bloggers and pet influencers, with audience/blog eligibility reported", "compensation": "A $60 flat bounty per sale is strong pay, plus 5% recurring on subscriptions; figures are third-party reported and one source differs, and no cap statement exists", "contact_access": "Published contact email on the official affiliate page plus the Impact application route", "opportunity_availability": "Application via Impact with reported audience and blog requirements \u2014 not instant or open to all", "credibility": "Established fresh-pet-food brand with consistent program reporting across multiple independent roundups"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('JustFoodForDogs', 'https://justfoodfordogs.com', 'Maker of fresh, human-grade, veterinarian-recommended dog food, treats and supplements, sold through justfoodfordogs.com and its own retail kitchens. Its official Ambassadors/Affiliates page recruits both social content creators and traditional affiliate partners, paying a percentage of every sale and subscription — but the brand publishes no percentage itself, and third-party rate reports conflict.', 'United States', 'published') returning id into bid;
