  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'JustFoodForDogs Ambassadors/Affiliates — dedicated social-creator path plus traditional affiliate path on the official page; published rate reports conflict (8%/10%/up to 28%), so the rate is unsettled', 'https://justfoodfordogs.com/pages/ambassadors-affiliates', 'https://justfoodfordogs.com/pages/ambassadors-affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://justfoodfordogs.com/pages/ambassadors-affiliates', 'official_site', 'creator_program', 'JustFoodForDogs'' official Ambassadors/Affiliates page fetched in full: two paths — ''Social Content Creater'' for influencers, YouTubers, TikTokers and dog-loving content creators sharing links in bios, stories and videos, and ''Traditional Affiliate Partner'' for bloggers, marketers and email list owners with dashboard tracking. Both ''earn a percentage of every product sale, subscription, or one-time purchase'' through a referral link; the page publishes NO percentage and NO network name.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/justfoodfordogs/', 'listing', 'affiliate', 'Third-party rate reports conflict, so commission_rate is null: Lasso, Dogster and UpPromote report 10% per sale (UpPromote names CJ Affiliate as the network; Lasso''s niche roundup names ShareASale), an older roundup reports 8%, and PostAffiliatePro claims ''up to 28%''. The network is recorded as CJ Affiliate per the most detailed recent sources, with the ShareASale conflict documented here. No earnings-cap statement is published, so the cap is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 17, 10, 11, 8, 5, '{"niche_fit": "Fresh human-grade dog food from a category-defining brand is a top-tier demonstrable pet product", "ugc_evidence": "A dedicated social content creator path named on the brand''s own page, alongside a traditional affiliate track \u2014 strong UGC evidence", "compensation": "Pay is a percentage of every sale and subscription, but the brand publishes no figure and third-party reports conflict, so compensation is scored on the unsettled evidence", "contact_access": "Application routes for both creator and affiliate paths are published on the official page; no direct email is published", "opportunity_availability": "Open application on the brand''s own page for creators and publishers alike", "credibility": "Long-established, veterinarian-recommended fresh food brand with physical retail kitchens"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Jinx', 'https://thinkjinx.com', 'Premium pet food brand selling kibble, wet food, treats and toppers for dogs and cats with superfoods and probiotics, through thinkjinx.com and major retailers. Its affiliate program runs on the Rakuten network (Program ID 45890) and actively recruits pet bloggers and influencers; published rate reporting is limited to an ''up to 5–10%'' range from aggregators.', 'United States', 'published') returning id into bid;
