  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://tbsmo.com/digital-marketing-services-nj/affiliate-marketing/affiliate-sign-up/jinx-affiliateprogram/', 'listing', 'affiliate', 'The Jinx affiliate program page operated by its affiliate agency (Today''s Business) states the program runs on the Rakuten affiliate network with Program ID 45890, targets pet parents in the United States, and explicitly welcomes pet bloggers and dog influencers alongside content, review, cashback and loyalty publishers. The page publishes no commission percentage.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopper.com/partnerships/thinkjinx-com-affiliate-program', 'listing', 'affiliate', 'Shopper''s partnership listing reports the Jinx payout only as ''up to 5-10% per sale''. An ''up to'' range from a single aggregator is a ceiling, not a settled rate, so commission_rate is null with the reported range documented here. No earnings-cap statement is published, so the cap is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://thinkjinx.com', 'official_site', 'creator_program', 'Jinx''s official homepage fetched in full: premium food, toppers and treats ''expertly-crafted with high quality proteins, superfoods, and probiotics'', recipes backed by a council of pet nutritionists, veterinarians and formulators, a public partnership with Chris Evans, and 1% of every purchase donated to pets in need.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 10, 10, 8, 4, '{"niche_fit": "Premium kibble, treats and toppers for dogs and cats are mainstream, highly content-friendly pet products", "ugc_evidence": "The program explicitly recruits pet bloggers and dog influencers, and the brand runs celebrity-led social campaigns", "compensation": "Only an aggregator''s ''up to 5\u201310%'' range is published \u2014 a ceiling, not a settled rate \u2014 and no cap statement exists", "contact_access": "Program application runs through Rakuten and the brand''s affiliate agency page; no clean public program email (the agency page''s contact address is a mangled staging address and is not recorded)", "opportunity_availability": "Open to US-traffic publishers and influencers through a major network", "credibility": "Established national brand sold in major retailers with a celebrity partnership, though program terms are thinly published"}'::jsonb);
