  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/21501?setLocale=de_DE', 'listing', 'affiliate', 'KatKin''s Awin merchant profile (programme 21501) fetched in full: it describes 100% fresh premium meat cat food developed by in-house vets and nutritionists, publishes keyword policy (no bidding on the KatKin brand) and voucher policy (no commission on orders using non-affiliate vouchers), and suggested affiliate copy. The public profile shows NO commission rate and NO earnings-cap statement, so commission_rate is null and the cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://katkin.com', 'official_site', 'creator_program', 'KatKin''s official homepage fetched in full: fresh food made from 100% human-quality meats, recipes designed by a Board-Certified Vet Nutritionist, personalised portions delivered to the door, rated 4.7/5 from 14,445 Trustpilot reviews, with an active ''ad vocates'' community invited to tag and share content.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 9, 10, 7, 5, '{"niche_fit": "Fresh personalised cat food is a premium subscription product with a passionate, content-active cat-parent audience", "ugc_evidence": "A live programme on a major network with published affiliate copy and policies; no dedicated creator tier is published", "compensation": "No commission rate is published on the public Awin profile, so compensation cannot be scored higher on evidence", "contact_access": "Application is through the Awin programme page; no direct affiliate email is published", "opportunity_availability": "Open to Awin publishers, but the brand ships UK-only, limiting the creator pool to UK audiences", "credibility": "Highly rated UK brand (4.7/5 from 14,445 Trustpilot reviews on its own homepage) with vet-designed recipes"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('FLAVORS Food Toppers', 'https://basicsbrands.com', 'Beaumont Products'' pet brand of human-grade food toppers for picky dogs and cats, sold at basicsbrands.com. Its Basics Affiliate Program pays a published 10% starting commission (increases at the brand''s discretion), with a 60-day cookie and monthly payouts — restricted to US-based outlets with a large pet-owner audience.', 'United States', 'published') returning id into bid;
