  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Basics Affiliate Program (Beaumont Products) — FLAVORS food toppers; published 10% starting commission, 60-day cookie; US-based outlets with a large pet audience only', 'https://flavorsfoodtoppers.com/pages/become-an-affiliate', 'https://flavorsfoodtoppers.com/pages/become-an-affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://flavorsfoodtoppers.com/pages/become-an-affiliate', 'official_site', 'affiliate', 'The official ''Become an Affiliate'' page for Beaumont Products'' Basics Affiliate Program fetched in full, including its FAQ: ''We pay a starting commission rate of 10%. Higher volume affiliates will eligible for commission up to 25%'' with increases ''up to Basics'' sole discretion'', a 60-day cookie, no fees, and monthly payment by check, direct deposit or PayPal once a $50 balance is reached. The discretionary up-to-25% is not a guaranteed tier, so the recorded rate is the published 10% starting rate. No earnings-cap statement is published, so the cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://flavorsfoodtoppers.com/pages/become-an-affiliate', 'official_site', 'affiliate', 'The same official FAQ states the gates honestly: applications only from outlets based in the USA that ''appear to have a large audience of pet owners'', and the brand may refuse or revoke membership at its sole discretion. It also confirms sales are generated at basicsbrands.com, whose storefront presents FLAVORS human-grade food toppers for picky dogs and cats (currently directing shoppers to Amazon while the site is refreshed).', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 12, 12, 10, 6, 4, '{"niche_fit": "Food toppers for picky eaters are an easy, demonstrable add-on product for dog and cat content", "ugc_evidence": "A standing affiliate program explicitly open to social media personalities, bloggers and content publishers", "compensation": "A published 10% starting rate is fair mid-range pay; increases to up to 25% are discretionary rather than a published tier, and no cap statement exists", "contact_access": "Application via the official program page; no direct affiliate email is published", "opportunity_availability": "Gated: US-based outlets only, and the brand expects a large pet-owner audience \u2014 smaller creators may be refused", "credibility": "Program terms and FAQ are fully published by the parent company, though the brand itself is small and its storefront is mid-refresh"}'::jsonb);
