  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'My Dog Foo Affiliate Program — 10% starting commission via Affiliatly, affiliates worldwide, $50 PayPal threshold (storefront flagged for re-check)', 'https://www.affiliatly.com/af-1018498/affiliate.panel?mode=faq_text', 'https://www.affiliatly.com/af-1018498/affiliate.panel?mode=faq_text', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affiliatly.com/af-1018498/affiliate.panel?mode=faq_text', 'official_site', 'affiliate', 'My Dog Foo''s official affiliate FAQ on its Affiliatly portal fetched in full: ''We pay starting at a 10% commission rate. Higher volume affiliates are eligible for higher commission levels at our sole discretion'', no participation fees, a 15-day cookie, payment via PayPal on the last Friday of the month at a $50 threshold, real-time portal reporting, and ''We accept affiliates from anywhere in the world''. No earnings-cap statement is published, so the cap is unknown; the recorded rate is the published 10% starting rate.', 'verified', now());
