  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 10, 12, 13, 9, 3, '{"niche_fit": "A small dog food brand is a plausible pet-content fit, though its product range and audience are narrow", "ugc_evidence": "A real, terms-published affiliate program, but no dedicated creator or UGC programme is evidenced", "compensation": "Published 10% starting rate with discretionary increases; fair for a small brand, with no cap statement published", "contact_access": "Published program email (bark@mydogfoo.com) plus the Affiliatly application portal \u2014 the best contact access in this batch", "opportunity_availability": "Open worldwide with no minimum sales level to stay in the program", "credibility": "Very small brand; storefront could not be independently fetched in this pass, so credibility is scored conservatively"}'::jsonb);
