  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://merchants.sovrn.com/merchants/104272/bedsure-affiliate-program', 'listing', 'affiliate', 'Sovrn Commerce''s own Bedsure merchant page states that ''a live Bedsure–Sovrn partnership cannot be independently verified here'' and that current commission rates through Sovrn could not be verified; Shopper separately reports ''up to 10%''. Because the reported rates conflict (7.5% vs 10%) and the network route is unverified by the network itself, commission_rate is null, the network is recorded as Sovrn Commerce with this caveat, and the cap is unknown (no cap statement anywhere). Flagged needs_review.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 11, 8, 8, 8, 4, '{"niche_fit": "Bedding and home textiles are a staple home-content category with constant refresh and seasonal angles", "ugc_evidence": "Affiliate listings exist and the brand is heavily promoted by creators on marketplaces, but no brand-published creator program was found", "compensation": "Reported rates conflict and are only ''up to'' ceilings, so compensation is scored low on evidence", "contact_access": "No brand-published affiliate contact or application page could be settled; access is via network/aggregator listings", "opportunity_availability": "Listings suggest open joining, but the underlying program route needs verification before creators rely on it", "credibility": "A large, widely sold home-textiles brand, though its affiliate program documentation is unusually murky"}'::jsonb);
